def numeroter_paiements_existants(apps, schema_editor):
    """Donne un numéro de reçu aux paiements enregistrés avant cette version."""
    Paiement = apps.get_model("paiements", "Paiement")
    for p in Paiement.objects.filter(numero_recu__isnull=True).only("id", "date_paiement").iterator():
        annee = p.date_paiement.year if p.date_paiement else 2026
        Paiement.objects.filter(pk=p.pk).update(numero_recu=f"REC-{annee}-{p.pk:06d}")


